import React, { useState } from 'react';

export default function App() {
  const [valorPrincipal, setValorPrincipal] = useState(0);
  const [porcentagemHonorarios, setPorcentagemHonorarios] = useState(20);
  const [dataIntimacao, setDataIntimacao] = useState('');
  const [prazoDias, setPrazoDias] = useState(15);

  // Lógica de Honorários
  const valorHonorarios = (valorPrincipal * porcentagemHonorarios) / 100;
  const valorTotalCausa = Number(valorPrincipal) + valorHonorarios;

  // Lógica de Prazos (CPC - Dias Úteis)
  const calcularVencimento = () => {
    if (!dataIntimacao) return '---';
    let data = new Date(dataIntimacao + 'T00:00:00');
    let diasContados = 0;
    while (diasContados < prazoDias) {
      data.setDate(data.getDate() + 1);
      let diaSemana = data.getDay();
      if (diaSemana !== 0 && diaSemana !== 6) { // Pula Sábado (6) e Domingo (0)
        diasContados++;
      }
    }
    return data.toLocaleDateString('pt-BR');
  };

  const enviarRelatorio = () => {
    const texto = `*RELATÓRIO JURÍDICO - ADVOGADO JÁ*%0A%0A` +
      `💰 *Cálculo de Honorários:*%0A` +
      `- Valor da Causa: R$ ${Number(valorPrincipal).toLocaleString('pt-BR')}%0A` +
      `- Honorários (${porcentagemHonorarios}%): R$ ${valorHonorarios.toLocaleString('pt-BR')}%0A` +
      `- *Total Estimado: R$ ${valorTotalCausa.toLocaleString('pt-BR')}*%0A%0A` +
      `📅 *Controle de Prazo:*%0A` +
      `- Data Inicial: ${dataIntimacao ? new Date(dataIntimacao).toLocaleDateString('pt-BR') : 'Não informada'}%0A` +
      `- Prazo: ${prazoDias} dias úteis%0A` +
      `- *VENCIMENTO FINAL: ${calcularVencimento()}*`;

    window.open(`https://wa.me/?text=${texto}`);
  };

  return (
    <div style={styles.container}>
      <header style={styles.header}>
        <h1 style={{margin: 0}}>⚖️ Advogado Já Pro</h1>
        <p style={{fontSize: '0.9rem', opacity: 0.8}}>Inteligência Jurídica Rápida</p>
      </header>

      <main style={styles.main}>
        {/* Bloco de Honorários */}
        <section style={styles.card}>
          <h2 style={styles.cardTitle}>💰 Honorários e Valores</h2>
          <label style={styles.label}>Valor da Causa (R$)</label>
          <input type="number" style={styles.input} onChange={(e) => setValorPrincipal(e.target.value)} />
          
          <label style={styles.label}>Honorários (%)</label>
          <input type="number" value={porcentagemHonorarios} style={styles.input} onChange={(e) => setPorcentagemHonorarios(e.target.value)} />
          
          <div style={styles.resultBox}>
            <p>Sua parte: <strong>R$ {valorHonorarios.toLocaleString('pt-BR', {minimumFractionDigits: 2})}</strong></p>
          </div>
        </section>

        {/* Bloco de Prazos */}
        <section style={styles.card}>
          <h2 style={styles.cardTitle}>📅 Calculadora de Prazos (CPC)</h2>
          <label style={styles.label}>Data da Intimação</label>
          <input type="date" style={styles.input} onChange={(e) => setDataIntimacao(e.target.value)} />
          
          <label style={styles.label}>Prazo (Dias Úteis)</label>
          <select style={styles.input} onChange={(e) => setPrazoDias(Number(e.target.value))} value={prazoDias}>
            <option value="5">5 dias (Manifestação)</option>
            <option value="15">15 dias (Recurso/Contestação)</option>
            <option value="30">30 dias (Especial)</option>
          </select>

          <div style={{...styles.resultBox, background: '#fff5f5'}}>
            <p>Vencimento Final: <strong style={{color: '#c0392b'}}>{calcularVencimento()}</strong></p>
          </div>
        </section>

        <button onClick={enviarRelatorio} style={styles.button}>
          📤 ENVIAR RESUMO POR WHATSAPP
        </button>
      </main>
    </div>
  );
}

const styles = {
  container: { background: '#f0f2f5', minHeight: '100vh', fontFamily: 'Segoe UI, Tahoma, sans-serif' },
  header: { background: '#2c3e50', color: 'white', padding: '30px 20px', textAlign: 'center' },
  main: { maxWidth: '500px', margin: '0 auto', padding: '20px' },
  card: { background: 'white', padding: '20px', borderRadius: '12px', boxShadow: '0 4px 6px rgba(0,0,0,0.1)', marginBottom: '20px' },
  cardTitle: { fontSize: '1.1rem', marginTop: 0, color: '#2c3e50', borderBottom: '1px solid #eee', paddingBottom: '10px' },
  label: { display: 'block', fontSize: '0.8rem', color: '#666', marginBottom: '5px' },
  input: { width: '100%', padding: '12px', marginBottom: '15px', borderRadius: '8px', border: '1px solid #ddd', boxSizing: 'border-box', fontSize: '1rem' },
  resultBox: { background: '#f8f9fa', padding: '10px', borderRadius: '8px', textAlign: 'center', fontSize: '1.1rem' },
  button: { width: '100%', padding: '18px', background: '#27ae60', color: 'white', border: 'none', borderRadius: '12px', fontWeight: 'bold', fontSize: '1rem', cursor: 'pointer', boxShadow: '0 4px 10px rgba(39, 174, 96, 0.3)' }
};
